// Convert already represented floating values. Literal admission is separate:
// explicit narrowing may overflow to infinity, and preserves signed zero.
FloatingBits :: (bits: uint64, from: int, to: int) -> uint64 {
    if (from == to) {
        return bits;
    }
    if (from == DoubleStorage) {
        sign := (bits >> uint(32)) & uint64(0x80000000);
        exponent := int((bits >> uint(52)) & uint64(0x7ff));
        fraction := bits & uint64(0xfffffffffffff);
        if (exponent == 2047 && fraction != 0) {
            return sign | uint64(0x7fc00000);
        }
        if (exponent > 1150) {
            return sign | uint64(0x7f800000);
        }
        if (exponent == 0) {
            return sign;
        }
        return sign | uint64(FloatFromDouble(exponent, int64(fraction)));
