// rounds: half to even, a value past the largest binary32 to a signed
// infinity, and a NaN to a quiet one.
pub NarrowedBits :: (bits: uint64) -> uint64 {
    sign := (bits >> 63) << 31;
    exponent := int((bits >> 52) & 0x7FF);
    fraction := bits & 0xFFFFFFFFFFFFF;
    if (exponent == 0x7FF && fraction != 0) {
        return sign | 0x7FC00000;
    }
    if (exponent == 0x7FF) {
        return sign | 0x7F800000;
    }
    if (exponent == 0) {
        // A binary64 subnormal is below half the least binary32 subnormal.
        return sign;
